      await $storex.projects.saveKanban({ project: targetProject })

      // 3. Allocate the new chat ids first, so inter-task links can be remapped.
      const idMap = {}
      sourceChats.forEach(sourceChat => {
        if (sourceChat?.id) idMap[sourceChat.id] = uuidv4()
